<template>
  <div class="crosshairBox">
    <div class="layers">
      <draggable
        :list="layers"
        item-key="name"
        v-bind="dragOptions"
        handle=".handle"
      >
        <template #item="{ element, index }">
          <div class="layer">
            <config-box
              @removeLayer="removeLayer"
              :index="index"
              :setting="element"
              @updateLayer="updateLayer"
            />
          </div>
        </template>
      </draggable>
      <div class="addLayer">
        <button
          v-wave="{
            color: 'rgb(91, 145, 254)',
          }"
          @click="addLayer()"
        >
          Add layer
        </button>
        <CustomSelect
          id="crosshairTypes"
          @change="changeType"
          :options="types"
        />
      </div>
    </div>
    <div class="right">
      <div :style="{ backgroundImage: `url(${background})` }" class="preview">
        <crosshair-render :layers="layers" :h="`200px`" :w="`200px`" />
      </div>
    </div>
  </div>
</template>

<script>
import ConfigBox from "./ConfigBox.vue";
// TODO Uljepsat code. (Mozda sa vue style classama)
// TODO Stavi da preview mude position absolute na top right. (Tako da kad scrollaju kroz crosshair settings da je uvjek vidljiv)
// TODO Dodat da mozes dodavati vise elementa od drugit typova aka stekanje typova. (Jedan preko drugog sa position absolute)
// TODO Dodoati jos typova. (Circle etc)
import CrosshairRender from "./CrosshairRender.vue";
import draggable from "vuedraggable";
import CustomSelect from "../../CustomSelect.vue";

export default {
  //Types: 1 = default
  name: "crosshair-box",
  components: { CrosshairRender, ConfigBox, draggable, CustomSelect },
  props: ["devMode"],
  computed: {
    dragOptions() {
      return {
        animation: 200,
      };
    },
  },
  data() {
    return {
      drag: false,
      types: [
        { name: "Cross", value: "1" },
        { name: "Circle", value: "2" },
      ],
      type: 1,
      layers: [],
      background: require("../../../assets/crosshair_bg.png"),
    };
  },
  watch: {
    layers: {
      handler(val) {
        console.log(JSON.stringify(val));
        if (this.devMode) return;
        // eslint-disable-next-line no-undef
        mp.trigger("SaveCrosshair", JSON.stringify(val));
      },
      deep: true,
    },
  },
  methods: {
    changeType(type) {
      this.type = parseInt(type);
    },
    removeLayer(index) {
      this.layers.splice(index, 1);
    },
    updateLayer(index, updatedLayer) {
      this.layers[index] = updatedLayer;
    },
    addLayer() {
      if (this.layers.length >= 100)
        return global.Swal.fire({
          icon: "error",
          title: "Limit Reached",
          text: "You reached 100 layers limit",
          footer: "If you really need more then this contact us 🤨",
        });

      switch (this.type) {
        case 1:
          this.layers.push({
            name: "Layer Cross",
            hidden: false,
            sides: [true, true, true, true],
            type: 1,
            gap: "20",
            size: "20",
            width: "3",
            rotation: "0",
            radius: "0",
            color: "#e66465",
            outline: {
              enable: false,
              width: "1",
              color: "#000",
            },
            dot: {
              enabled: false,
              size: "3",
              radius: "0",
              color: "#e66465",
            },
          });
          break;
        case 2:
          this.layers.push({
            name: "Layer Circle",
            hidden: false,
            type: 2,
            width: "2",
            color: "#e66465",
            size: {
              separated: false,
              y: "20",
              x: "20",
            },
            rotation: "0",
            fill: {
              enabled: false,
              color: "#fff",
            },
            outline: {
              enabled: false,
              width: "2",
              color: "#000",
            },
          });
          break;
      }
    },
  },
};
</script>

<style lang="scss" scoped>
.crosshairBox {
  margin-top: 10px;
  background: $foreground;
  border-radius: 15px;
  padding: 10px;
  color: #f1f1f1;
  min-height: 500px;
  max-height: 500px;
  display: flex;
  max-width: 600px;

  .layers {
    flex: 1;
    margin-right: 10px;
    max-height: 500px;
    overflow-y: auto;
    padding-right: 5px;
    border-radius: 5px;

    .layer {
      margin-bottom: 5px;
    }
  }

  .addLayer {
    background: lighten($foreground, 10%);
    border-radius: 5px;
    padding: 10px;
    border: 2px dashed rgba($blue, 0.3);
    color: $white-text;
    display: flex;
    justify-content: center;
    align-items: center;

    button {
      font-weight: bold;
      background: red;
      padding: 13px 20px;
      color: $blue;
      background: rgba($blue, 0.3);
      border-radius: 5px;
      transition: background 0.4s;
      margin-right: 10px;

      &:hover {
        background: rgba($blue, 0.4);
      }
    }
  }

  .right {
    display: flex;
    flex-direction: column;
    justify-content: flex-start;
    align-items: center;

    .preview {
      width: 200px;
      height: 200px;
      border-radius: 15px;
      right: 10px;
      box-shadow: rgba(0, 0, 0, 0.35) 0px 5px 15px;
    }
  }
}
</style>
