<template>
  <input
    type="color"
    :value="modelValue"
    @input="$emit('update:modelValue', $event.target.value)"
  />
</template>

<script>
export default {
  name: "custom-color",
  props: ["modelValue"],
};
</script>

<style lang="scss" scoped>
input {
  background: darken($gray, 5%);
  height: 35px;
  width: 50px;
  padding: 3px;
  border-radius: 5px;
}
</style>
