<template>
  <div class="h-full min-h-full w-full min-w-full" v-show="title === selectedTitle">
    <slot />
  </div>
</template>

<script>
import { inject } from "vue";

export default {
  name: "Tab",
  props: ["title"],
  setup() {
    const selectedTitle = inject("selectedTitle");
    const tabTitles = inject("tabTitles");

    return {
      selectedTitle,
      tabTitles,
    };
  },
};
</script>

<style scoped lang="scss"></style>
